	Cvss         *WpCvss    `json:"cvss"`
	CreatedAt    time.Time  `json:"created_at"`
	UpdatedAt    time.Time  `json:"updated_at"`
	VulnType     string     `json:"vuln_type"`
	References   References `json:"references"`
	FixedIn      string     `json:"fixed_in"`
}

// WpCvss is the CVSS information supplied by WPScan Enterprise.
type WpCvss struct {
	Score    float64 `json:"score"`
	Vector   string  `json:"vector"`
	Severity string  `json:"severity"`
}

// References is for wpscan json
type References struct {
	URL     []string `json:"url"`
	Cve     []string `json:"cve"`
	Secunia []string `json:"secunia"`
}

// DetectWordPressCves access to wpscan and fetch scurity alerts and then set to the given ScanResult.
	for _, vulnerability := range cves {
		cveID := fmt.Sprintf("WPVDBID-%s", vulnerability.ID)
		if len(vulnerability.References.Cve) > 0 {
			cveID = "CVE-" + vulnerability.References.Cve[0]
		}

		var refs []models.Reference
		for _, url := range vulnerability.References.URL {
			refs = append(refs, models.Reference{
				Link: url,
			})
		}

		optional := map[string]string{}
		if vulnerability.Poc != "" {
			optional["poc"] = vulnerability.Poc
		}
		if vulnerability.IntroducedIn != "" {
			optional["introduced_in"] = vulnerability.IntroducedIn
		}
		content := models.CveContent{
			Type:         models.WpScan,
			CveID:        cveID,
			Title:        vulnerability.Title,
			Summary:      vulnerability.Description,
			References:   refs,
			Published:    vulnerability.CreatedAt.UTC(),
			LastModified: vulnerability.UpdatedAt.UTC(),
			Optional:     optional,
		}
		if vulnerability.Cvss != nil {
			content.Cvss3Score = vulnerability.Cvss.Score
			content.Cvss3Vector = vulnerability.Cvss.Vector
			content.Cvss3Severity = vulnerability.Cvss.Severity
		}
		vinfos = append(vinfos, models.VulnInfo{
			CveID:       cveID,
			CveContents: models.NewCveContents(content),
			VulnType:    vulnerability.VulnType,
			Confidences: []models.Confidence{
				models.WpScanMatch,
			},
			WpPackageFixStats: []models.WpPackageFixStatus{{
				Name:    pkgName,
				FixedIn: vulnerability.FixedIn,
			}},
		})
	}
	return
}

